#!/usr/bin/env python3
"""Install the reviewed procurement source in this GitHub repository. No credentials included."""
from pathlib import Path, PurePosixPath
import base64, hashlib, io, subprocess, zipfile
PAYLOAD = """"""
SHA256 = "dafe4d092db0ddf8d15a0b54b85cfd4d7c4ff9841bf8115fb035775ddfe94367"
root = Path(__file__).resolve().parent
repo = subprocess.run(['git','-C',str(root),'rev-parse','--show-toplevel'],capture_output=True,text=True)
if repo.returncode or Path(repo.stdout.strip()).resolve()!=root:
    raise SystemExit('Upload this file to the root of your GitHub repository, then run it in Codespaces.')
raw=base64.b64decode(PAYLOAD)
if hashlib.sha256(raw).hexdigest()!=SHA256:
    raise SystemExit('The installer is incomplete. Download it again.')
with zipfile.ZipFile(io.BytesIO(raw)) as archive:
    entries=archive.infolist()
    for entry in entries:
        name=PurePosixPath(entry.filename)
        if name.is_absolute() or '..' in name.parts or not name.parts or name.parts[0]=='.git':
            raise SystemExit('Invalid archive entry')
        target=root.joinpath(*name.parts)
        if root not in target.resolve().parents:
            raise SystemExit('Invalid archive path')
        if target.exists() and entry.filename not in {'README.md','.gitignore'}:
            if not target.is_file() or target.read_bytes()!=archive.read(entry):
                raise SystemExit('Existing file would change: '+entry.filename+'. Keep your changes before installing.')
    for entry in entries:
        target=root/entry.filename
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(archive.read(entry))
print('Procurement source installed. Review git status, then commit and push as described in README.md.')
